mapper.select:
SELECT n.id AS id, n.title, n.content, n.category, n.writer_id AS writerId, u.name AS writerName, n.view_count AS viewCount, n.is_important AS important, n.target_role AS targetRole, n.created_at AS createdAt, n.updated_at AS updatedAt FROM notices n LEFT JOIN users u ON n.writer_id = u.id
n.category = #{category}
AND n.title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY n.is_important DESC, n.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT n.id AS id, n.title, n.content, n.category, n.writer_id AS writerId, u.name AS writerName, n.view_count AS viewCount, n.is_important AS important, n.target_role AS targetRole, n.created_at AS createdAt, n.updated_at AS updatedAt FROM notices n LEFT JOIN users u ON n.writer_id = u.id WHERE (n.target_role = 'ALL' OR n.target_role = #{userRole} OR n.target_role IS NULL)
AND n.category = #{category}
AND n.title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY n.is_important DESC, n.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM notices
category = #{category}
AND title LIKE CONCAT('%', #{keyword}, '%')

SELECT COUNT(*) FROM notices n WHERE (n.target_role = 'ALL' OR n.target_role = #{userRole} OR n.target_role IS NULL)
AND n.category = #{category}
AND n.title LIKE CONCAT('%', #{keyword}, '%')

mapper.update:
UPDATE notices
SET view_count = view_count + 1
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM notice_attachments a LEFT JOIN notices n ON a.notice_id = n.id WHERE a.is_deleted = FALSE
AND n.category = #{category}
AND a.original_file_name LIKE CONCAT('%', #{keyword}, '%')

SELECT a.*, n.category, u.name AS writerName FROM notice_attachments a LEFT JOIN notices n ON a.notice_id = n.id LEFT JOIN users u ON n.writer_id = u.id WHERE a.is_deleted = FALSE
AND n.category = #{category}
AND a.original_file_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY a.uploaded_at DESC LIMIT #{limit} OFFSET #{offset}
